<?php
$checks = []; $failures = []; $warnings = [];
set_error_handler(function($level,$message) use (&$warnings) { $warnings[]=$message; return true; });
function check($ok,$message) { global $checks,$failures,$current; $checks[$current]=($checks[$current]??0)+1; if (!$ok) $failures[$current][]=$message; }
function eq($a,$b,$label) { check($b==='' ? $a==='' : (is_numeric($a)&&is_numeric($b) ? round((float)$a,2)===round((float)$b,2) : $a===$b),$label.' expected '.json_encode($b).' got '.json_encode($a)); }
function ctx($name) { global $fixture; wp_set_current_user($fixture['users'][$name]); WC()->customer=new WC_Customer($fixture['users'][$name]); WC()->cart->empty_cart(false); wc_clear_notices(); }
function admin_ctx() { $ids=get_users(['role'=>'administrator','number'=>1,'fields'=>'ID']); wp_set_current_user((int)$ids[0]); }
function pid($n) { global $fixture; return $fixture['products'][$n]; }
function api($method,$route,$body=null) { $r=new WP_REST_Request($method,'/cewp/v1/'.$route); if ($body!==null) { $r->set_header('content-type','application/json'); $r->set_body(wp_json_encode($body)); } return rest_do_request($r); }
function rule($product,$type='fixed',$value=60,$role='test_contract',$extra=[]) { return array_merge(['product_id'=>$product,'variation_id'=>0,'scope_type'=>'role','scope_value'=>$role,'price_type'=>$type,'price_value'=>$value,'min_qty'=>1],$extra); }
function cart($id,$qty,$coupon=false) { WC()->cart->empty_cart(false); wc_clear_notices(); $p=wc_get_product($id); $key=$p->is_type('variation')?WC()->cart->add_to_cart($p->get_parent_id(),$qty,$id,$p->get_variation_attributes()):WC()->cart->add_to_cart($id,$qty); check((bool)$key,'cart added'); $applied=$coupon?WC()->cart->apply_coupon('char-ten'):null; $out=[]; for($i=0;$i<3;$i++) { WC()->cart->calculate_totals(); $item=WC()->cart->get_cart()[$key]; $out[]=[$item['data']->get_price('edit'),$item['data']->get_price(),$item['line_subtotal'],$item['line_total'],WC()->cart->get_total('edit')]; } return [$applied,$out]; }
function tuple($actual,$expected,$label) { foreach($expected as $k=>$v) eq($actual[$k],$v,$label.'/'.$k); }
function text_html($html) { return html_entity_decode(strip_tags($html),ENT_QUOTES|ENT_HTML5,'UTF-8'); }
function expected($name,$dealer,$qty=1) { $retail=$name==='on_sale'?80:($name==='variation_large'?120:100); if(!$dealer) return $retail; return match($name) {'on_sale'=>80,'fixed'=>60,'fixed_cap'=>50,'percent','zero_cap','variation_small'=>90,'percent_cap','discount_cap'=>70,'discount'=>85,'tier'=>$qty>=5?75:90,'date_active'=>65,'variation_large'=>108,default=>$retail}; }
function csv_probe($contents) { global $warnings; admin_ctx(); $tmp=tempnam(sys_get_temp_dir(),'cewp-test-'); file_put_contents($tmp,$contents); $_FILES['csv_file']=['tmp_name'=>$tmp,'error'=>UPLOAD_ERR_OK]; $_REQUEST['_wpnonce']=wp_create_nonce('cewp_import_csv'); $url=null; $hook=function($u)use(&$url){$url=$u;throw new RuntimeException('TEST_REDIRECT');}; add_filter('wp_redirect',$hook,999); $before=count($warnings); try { CEWP\Import::handle(); } catch(RuntimeException $e) {if($e->getMessage()!=='TEST_REDIRECT')throw $e;} finally {remove_filter('wp_redirect',$hook,999); unlink($tmp);} parse_str(parse_url($url,PHP_URL_QUERY),$q); return [$q,get_transient('cewp_import_errors'),array_slice($warnings,$before)]; }
